using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json.Serialization;
using ModelContextProtocol.Server;

namespace McpServerDemo;

/// <summary>
/// MCP tool classes are discovered by the SDK via [McpServerToolType].
/// Each [McpServerTool] method becomes a callable tool for the LLM.
/// Constructor parameters are resolved from DI automatically.
/// </summary>
[McpServerToolType]
public class WeatherTools
{
    private readonly HttpClient _http;

    // The SDK resolves constructor args from the DI container.
    // Because we register a named HttpClient ("weather"), we inject
    // IHttpClientFactory and create the client ourselves.
    public WeatherTools(IHttpClientFactory httpClientFactory)
    {
        _http = httpClientFactory.CreateClient("weather");
    }

    [McpServerTool, Description("Get current weather forecast for a US location by latitude/longitude.")]
    public async Task<string> GetForecast(
        [Description("Latitude (e.g. 47.6062)")] double latitude,
        [Description("Longitude (e.g. -122.3321)")] double longitude)
    {
        // NWS API: resolve grid point, then fetch forecast
        var point = await _http.GetFromJsonAsync<PointResponse>(
            $"/points/{latitude},{longitude}");

        if (point?.Properties?.ForecastUrl is null)
            return "Could not resolve forecast grid for that location.";

        var forecast = await _http.GetFromJsonAsync<ForecastResponse>(
            point.Properties.ForecastUrl);

        if (forecast?.Properties?.Periods is not { Count: > 0 })
            return "No forecast data available.";

        var lines = forecast.Properties.Periods
            .Take(5)
            .Select(p => $"{p.Name}: {p.Temperature}°{p.TemperatureUnit} – {p.ShortForecast}");

        return string.Join("\n", lines);
    }

    [McpServerTool, Description("Get active weather alerts for a US state (2-letter code, e.g. 'WA').")]
    public async Task<string> GetAlerts(
        [Description("Two-letter US state code")] string state)
    {
        var alerts = await _http.GetFromJsonAsync<AlertResponse>(
            $"/alerts/active/area/{state}");

        if (alerts?.Features is not { Count: > 0 })
            return "No active alerts for that state.";

        var lines = alerts.Features
            .Take(5)
            .Select(f => $"[{f.Properties.Severity}] {f.Properties.Headline}");

        return string.Join("\n", lines);
    }
}

// --- JSON models for the National Weather Service API ---

public record PointResponse
{
    [JsonPropertyName("properties")]
    public PointProperties? Properties { get; init; }
}

public record PointProperties
{
    [JsonPropertyName("forecast")]
    public string? ForecastUrl { get; init; }
}

public record ForecastResponse
{
    [JsonPropertyName("properties")]
    public ForecastProperties? Properties { get; init; }
}

public record ForecastProperties
{
    [JsonPropertyName("periods")]
    public List<ForecastPeriod>? Periods { get; init; }
}

public record ForecastPeriod
{
    [JsonPropertyName("name")]
    public string Name { get; init; } = "";

    [JsonPropertyName("temperature")]
    public int Temperature { get; init; }

    [JsonPropertyName("temperatureUnit")]
    public string TemperatureUnit { get; init; } = "";

    [JsonPropertyName("shortForecast")]
    public string ShortForecast { get; init; } = "";
}

public record AlertResponse
{
    [JsonPropertyName("features")]
    public List<AlertFeature>? Features { get; init; }
}

public record AlertFeature
{
    [JsonPropertyName("properties")]
    public AlertProperties Properties { get; init; } = new();
}

public record AlertProperties
{
    [JsonPropertyName("headline")]
    public string Headline { get; init; } = "";

    [JsonPropertyName("severity")]
    public string Severity { get; init; } = "";
}

