using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;

var builder = Host.CreateApplicationBuilder(args);

// Register a named HttpClient for the NWS API.
// This is resolved in WeatherTools via IHttpClientFactory.
builder.Services.AddHttpClient("weather", client =>
{
    client.BaseAddress = new Uri("https://api.weather.gov");
    client.DefaultRequestHeaders.UserAgent.ParseAdd("mcp-server-demo/1.0");
});

// Register the MCP server with stdio transport.
// WithToolsFromAssembly scans for [McpServerToolType] classes
// and registers them as transient services in DI automatically.
builder.Services
    .AddMcpServer()
    .WithStdioServerTransport()
    .WithToolsFromAssembly();

await builder.Build().RunAsync();

